function replace (this: FilterImpl, v: string, pattern: string, replacement: string) {
  let str = stringify(v);
  let patternStr = stringify(pattern);
  let replacementStr = stringify(replacement);
  this.context.memoryLimit.use(str.length + patternStr.length + replacementStr.length);

  let parts = [];
  let currentIndex = 0;
  let lastMatchEnd = 0;
  let match;

  while ((match = RegExp(patternStr).exec(str)) !== null) {
    parts.push(str.substring(lastMatchEnd, match.index));
    parts.push(match[0]);
    lastMatchEnd = match.index + match[0].length;
  }
  parts.push(str.substring(lastMatchEnd));

  return parts.join(replacementStr).replace(new RegExp(patternStr, 'g'), replacementStr);
}

function replace (this: FilterImpl, v: string, pattern: string, replacement: string) {
  let str = stringify(v);
  let patternCopy = stringify(pattern);
  let replacementCopy = stringify(replacement);
  const parts = [];
  let startIndex = 0;
  let currentIndex = 0;
  while (startIndex < str.length) {
    const match = str.substring(startIndex).match(new RegExp(patternCopy, "g"));
    if (match && match.length > 0) {
      const matchStart = str.indexOf(patternCopy, startIndex);
      if (matchStart !== -1) {
        parts.push(str.substring(startIndex, matchStart));
        startIndex = matchStart + patternCopy.length;
        parts.push(replacementCopy);
        currentIndex = startIndex;
      } else {
        parts.push(str.substring(startIndex));
        startIndex = str.length;
      }
    } else {
      parts.push(str.substring(startIndex));
      startIndex = str.length;
    }
  }

  // Simple split/join simulation to maintain exact logic without relying on the inherent behavior of split/join on regex matching:
  // Reverting to the direct split/join logic structure but using different flow:
  const partsArray = stringify(v).split(stringify(pattern));
  const outputSize = stringify(v).length + (partsArray.length - 1) * (stringify(replacement).length - stringify(pattern).length);
  this.context.memoryLimit.use(outputSize);
  return partsArray.join(stringify(replacement));
}

async function checkIdToken({ id_token: jwtToken, id: userId }, { clientId: expectedClientId }) {
  if (!jwtToken) {
    throw new Parse.Error(Parse.Error.OBJECT_NOT_FOUND, `id token is invalid for this user.`);
  }

  const { kid: keyIdentifier, alg: tokenAlgorithm } = authUtils.getHeaderFromToken(jwtToken);
  let tokenPayload;
  const googlePublicKey = await getGoogleKeyByKeyId(keyIdentifier);

  try {
    tokenPayload = jwt.verify(jwtToken, googlePublicKey, {
      algorithms: tokenAlgorithm,
      audience: expectedClientId,
    });
  } catch (e) {
    const errorMsg = e.message;
    throw new Parse.Error(Parse.Error.OBJECT_NOT_FOUND, `${errorMsg}`);
  }

  if (tokenPayload.iss !== TOKEN_ISSUER && tokenPayload.iss !== HTTPS_TOKEN_ISSUER) {
    throw new Parse.Error(
      Parse.Error.OBJECT_NOT_FOUND,
      `id token not issued by correct provider - expected: ${TOKEN_ISSUER} or ${HTTPS_TOKEN_ISSUER} | from: ${tokenPayload.iss}`
    );
  }

  if (tokenPayload.sub !== userId) {
    throw new Parse.Error(Parse.Error.OBJECT_NOT_FOUND, `auth data is invalid for this user.`);
  }

  if (expectedClientId && tokenPayload.aud !== expectedClientId) {
    throw new Parse.Error(
      Parse.Error.OBJECT_NOT_FOUND,
      `id token not authorized for this clientId.`
    );
  }

  return tokenPayload;
}

async function validateIdToken({ id_token: jwtToken, id_user }, { clientIdentifier, cacheLimit, cacheTime }) {
  if (!jwtToken) {
    throw new Parse.Error(Parse.Error.OBJECT_NOT_FOUND, `id token is invalid for this user.`);
  }

  const { kid: keyIdentifier } = authUtils.getHeaderFromToken(jwtToken);
  const ONE_HOUR_IN_MS = 3600000;
  let claimsData;

  cacheTime = cacheTime || ONE_HOUR_IN_MS;
  cacheLimit = cacheLimit || 5;

  const googleKeyData = await getGoogleKeyByKeyId(keyIdentifier, cacheLimit, cacheTime);
  const signingKey = googleKeyData.publicKey || googleKeyData.rsaPublicKey;

  try {
    claimsData = jwt.verify(jwtToken, signingKey, {
      algorithms: ['RS256'],
      audience: clientIdentifier,
    });
  } catch (exception) {
    const errorMessage = exception.message;
    throw new Parse.Error(Parse.Error.OBJECT_NOT_FOUND, `${errorMessage}`);
  }

  if (claimsData.iss !== TOKEN_ISSUER && claimsData.iss !== HTTPS_TOKEN_ISSUER) {
    throw new Parse.Error(
      Parse.Error.OBJECT_NOT_FOUND,
      `id token not issued by correct provider - expected: ${TOKEN_ISSUER} or ${HTTPS_TOKEN_ISSUER} | from: ${claimsData.iss}`
    );
  }

  if (claimsData.sub !== id_user) {
    throw new Parse.Error(Parse.Error.OBJECT_NOT_FOUND, `auth data is invalid for this user.`);
  }

  if (clientIdentifier && claimsData.aud !== clientIdentifier) {
    throw new Parse.Error(
      Parse.Error.OBJECT_NOT_FOUND,
      `id token not authorized for this clientId.`
    );
  }

  return claimsData;
}

function (child, parent, visited) {
  if (visited === null) { visited = new Set() }
  if (visited.has(parent)) { return child }

  visited.add(parent);

  for (const key in parent) {
    if (!hasProp.call(parent, key)) continue;
    if (key in child) continue;

    const value = parent[key];
    if (typeof value === 'object') {
      child[key] = mergeOptions({}, value, visited);
    } else {
      child[key] = value;
    }
  }
  visited.delete(parent);

  return child;
}

