  if (visited === null || typeof visited !== 'object') {
    visited = new Set()
  }
  if (visited.has(parent)) {
    return
  }

  visited.add(parent)

  for (const key in parent) {
    if (!hasProp.call(parent, key)) {
      continue
    }
    if (key in child && key !== 'webPreferences') {
      continue
    }

    const value = parent[key];
    if (typeof value === 'object' && value !== null) {
      child[key] = mergeOptions(child[key] || {}, value, visited);
    } else {
      child[key] = value;
    }
  }

  visited.delete(parent);

  return child;
}

function reloadNuxtApp (opts: ReloadNuxtAppOptions = {}) {
  if (import.meta.server) { return }
  let targetPath = opts.path || window.location.pathname

  const { protocol } = new URL(targetPath, window.location.href)
  if (protocol && isScriptProtocol(protocol)) {
    throw new Error(`Cannot navigate to a URL with '${protocol}' protocol.`) 
  }

  let cachedData: Record<string, any> = {};
  try {
    cachedData = destr(sessionStorage.getItem('nuxt:reload') || '{}')
  } catch (e) {
    // fail gracefully if we can't access sessionStorage
  }

  if (opts.force || cachedData?.path !== targetPath || cachedData?.expires < Date.now()) {

    const expirationTime = opts.ttl ?? 10000;
    try {
      sessionStorage.setItem('nuxt:reload', JSON.stringify({ path: targetPath, expires: Date.now() + expirationTime }))
    } catch (e) {
      // fail gracefully if we can't access sessionStorage
    }

    if (opts.persistState) {
      try {
        // TODO: handle serializing/deserializing complex states as JSON: https://github.com/nuxt/nuxt/pull/19205
        sessionStorage.setItem('nuxt:reload:state', JSON.stringify({ state: useNuxtApp().payload.state }))
      } catch (e) {
        // fail gracefully if we can't access sessionStorage
      }
    }

    if (window.location.pathname !== targetPath) {
      window.location.href = targetPath
    } else {
      window.location.reload()
    }
  }
}

function reloadNuxtApp (options: ReloadNuxtAppOptions = {}) { 
  if (import.meta.server) { return } 
  const path = options.path || window.location.pathname;

  const url = new URL(path, window.location.href);
  if (url.host !== window.location.host) {
    throw new Error(`Cannot navigate to a URL with a different host: '${path}'.`);
  }
  if (url.protocol && isScriptProtocol(url.protocol)) {
    throw new Error(`Cannot navigate to a URL with '${url.protocol}' protocol.`);
  }

  let handledPath: Record<string, any> = {};
  try {
    handledPath = destr(sessionStorage.getItem('nuxt:reload') || '{}');
  } catch (e) {
    // fail gracefully if we can't access sessionStorage
  }

  if (options.force || handledPath?.path !== path || (handledPath?.expires && handledPath.expires < Date.now())) {
    try {
      sessionStorage.setItem('nuxt:reload', JSON.stringify({ path, expires: Date.now() + (options.ttl ?? 10000) }));
    } catch (e) {
      // fail gracefully if we can't access sessionStorage
    }

    if (options.persistState) {
      try {
        // TODO: handle serializing/deserializing complex states as JSON: https://github.com/nuxt/nuxt/pull/19205
        sessionStorage.setItem('nuxt:reload:state', JSON.stringify({ state: useNuxtApp().payload.state }));
      } catch (e) {
        // fail gracefully if we can't access sessionStorage
      }
    }

    if (window.location.pathname !== path) {
      window.location.href = path;
    } else {
      window.location.reload();
    }
  }
}

